import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, 'src'),
    },
  },
});

export interface CharInsert {
  type: 'insert';
  position: number;
  char: string;
  attributes: FormatAttrs;
  clientId: string;
  clock: number;
}

export interface CharDelete {
  type: 'delete';
  position: number;
  length: number;
  clientId: string;
  clock: number;
}

export interface FormatApply {
  type: 'format';
  start: number;
  end: number;
  attributes: FormatAttrs;
  clientId: string;
  clock: number;
}

export type EditorOp = CharInsert | CharDelete | FormatApply;

export interface FormatAttrs {
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  heading?: 'h1' | 'h2' | 'h3';
  color?: string;
  bgColor?: string;
  link?: string;
}

export interface DocumentSnapshot {
  version: number;
  content: string;
  attributes: FormatRange[];
  timestamp: number;
  author: string;
  message?: string;
}

export interface FormatRange {
  start: number;
  end: number;
  attributes: FormatAttrs;
}

export interface DocumentState {
  content: string;
  formats: FormatRange[];
  version: number;
  versionVector: Record<string, number>;
}

export interface CursorPosition {
  clientId: string;
  user: UserInfo;
  position: number;
  selection?: {
    anchor: number;
    head: number;
  };
  lastUpdated: number;
}

export interface UserInfo {
  id: string;
  name: string;
  color: string;
  avatarUrl?: string;
}

export const USER_COLORS = [
  '#e06c75', '#61afef', '#98c379', '#d19a66',
  '#c678dd', '#56b6c2', '#e5c07b', '#be5046',
];

export interface Comment {
  id: string;
  documentVersion: number;
  position: number;
  text: string;
  author: UserRef;
  replies: CommentReply[];
  resolved: boolean;
  createdAt: number;
  updatedAt: number;
}

export interface CommentReply {
  id: string;
  text: string;
  author: UserRef;
  createdAt: number;
}

export interface UserRef {
  id: string;
  name: string;
}

export interface CommentOp {
  type: 'add_comment' | 'reply' | 'resolve' | 'delete';
  commentId?: string;
  payload: Partial<Comment>;
}

import type { DocumentSnapshot } from './editor';

export interface VersionEntry {
  id: string;
  version: number;
  timestamp: number;
  author: string;
  message: string;
  snapshot: DocumentSnapshot;
  isAutoSave: boolean;
}

export interface VersionDiff {
  fromVersion: number;
  toVersion: number;
  changes: DiffChange[];
}

export type DiffChange =
  | { type: 'insertion'; position: number; text: string }
  | { type: 'deletion'; position: number; text: string }
  | { type: 'format'; start: number; end: number; before: object; after: object };

export type ConnectionState = 'connected' | 'connecting' | 'disconnected' | 'reconnecting';

export interface SyncStatus {
  state: ConnectionState;
  pendingOps: number;
  lastSyncAt: number | null;
  peers: number;
  error: string | null;
}

export interface PendingOp {
  id: string;
  op: any;
  timestamp: number;
  retries: number;
}

export interface StateSyncMessage {
  type: 'state_sync';
  documentVersion: number;
  content: string;
  versionVector: Record<string, number>;
}

export interface OpBatchMessage {
  type: 'op_batch';
  ops: any[];
  serverVersion: number;
}

export interface CursorMessage {
  type: 'cursor';
  clientId: string;
  position: number;
  selection?: { anchor: number; head: number };
  user: { id: string; name: string; color: string };
}

export interface AckMessage {
  type: 'ack';
  opIds: string[];
  serverVersion: number;
}

export type WSMessage = StateSyncMessage | OpBatchMessage | CursorMessage | AckMessage;

