import { v4 as uuid } from 'uuid';
import type {
  CharInsert,
  CharDelete,
  FormatApply,
  EditorOp,
  FormatAttrs,
  FormatRange,
  DocumentState,
} from '../types/editor';

interface CRDTChar {
  id: string;
  char: string;
  originLeft: string | null;
  originRight: string | null;
  clientId: string;
  clock: number;
  deleted: boolean;
  attributes: FormatAttrs;
}

export class CRDTManager {
  private chars: CRDTChar[] = [];
  private versionVector: Record<string, number> = {};
  private clientId: string;
  private clock: number = 0;
  private pendingOps: EditorOp[] = [];
  private listeners: Array<(state: DocumentState) => void> = [];
  private formatRangesCache: FormatRange[] | null = null;
  private contentCache: string | null = null;

  constructor(clientId?: string) {
    this.clientId = clientId || uuid();
  }

  getClientId(): string {
    return this.clientId;
  }

  getClock(): number {
    return this.clock;
  }

  getVersionVector(): Record<string, number> {
    return { ...this.versionVector };
  }

  incrementClock(): number {
    this.clock += 1;
    this.versionVector[this.clientId] = this.clock;
    return this.clock;
  }

  getContent(): string {
    if (this.contentCache !== null) return this.contentCache;
    this.contentCache = this.chars.filter(c => !c.deleted).map(c => c.char).join('');
    return this.contentCache;
  }

  getFormatRanges(): FormatRange[] {
    if (this.formatRangesCache !== null) return this.formatRangesCache;

    const ranges: FormatRange[] = [];
    let currentAttrs: FormatAttrs | null = null;
    let rangeStart = 0;
    let pos = 0;

    for (const ch of this.chars) {
      if (ch.deleted) continue;
      const attrs = ch.attributes;
      const attrsKey = JSON.stringify(attrs);

      if (currentAttrs === null) {
        currentAttrs = attrs;
        rangeStart = pos;
      } else if (JSON.stringify(currentAttrs) !== attrsKey) {
        if (Object.keys(currentAttrs).length > 0) {
          ranges.push({ start: rangeStart, end: pos, attributes: { ...currentAttrs } });
        }
        currentAttrs = attrs;
        rangeStart = pos;
      }
      pos++;
    }

    if (currentAttrs !== null && Object.keys(currentAttrs).length > 0) {
      ranges.push({ start: rangeStart, end: pos, attributes: { ...currentAttrs } });
    }

    this.formatRangesCache = ranges;
    return ranges;
  }

  getState(): DocumentState {
    return {
      content: this.getContent(),
      formats: this.getFormatRanges(),
      version: this.clock,
      versionVector: this.getVersionVector(),
    };
  }

  onStateChange(listener: (state: DocumentState) => void): () => void {
    this.listeners.push(listener);
    return () => {
      this.listeners = this.listeners.filter(l => l !== listener);
    };
  }

  private notifyListeners(): void {
    const state = this.getState();
    for (const l of this.listeners) {
      l(state);
    }
  }

  insert(position: number, text: string, attributes: FormatAttrs = {}): EditorOp | null {
    if (text.length === 0) return null;

    const clock = this.incrementClock();
    const timestampedChars: CRDTChar[] = [];

    for (let i = 0; i < text.length; i++) {
      const leftId = this.getCharIdAtVisualPosition(position + i - 1);
      const rightId = this.getCharIdAtVisualPosition(position + i);

      timestampedChars.push({
        id: `${this.clientId}:${clock + i}`,
        char: text[i],
        originLeft: leftId,
        originRight: rightId,
        clientId: this.clientId,
        clock: clock + i,
        deleted: false,
        attributes: { ...attributes },
      });
    }

    this.clock += text.length - 1;
    this.versionVector[this.clientId] = this.clock;

    const op: CharInsert = {
      type: 'insert',
      position,
      char: text,
      attributes,
      clientId: this.clientId,
      clock,
    };

    this.applyInsertOp(op);
    this.invalidateCaches();
    this.notifyListeners();

    return op;
  }

  delete(start: number, length: number): EditorOp | null {
    if (length <= 0) return null;

    const clock = this.incrementClock();
    const op: CharDelete = {
      type: 'delete',
      position: start,
      length,
      clientId: this.clientId,
      clock,
    };

    this.applyDeleteOp(op);
    this.invalidateCaches();
    this.notifyListeners();

    return op;
  }

  format(start: number, end: number, attributes: FormatAttrs): EditorOp | null {
    if (start >= end) return null;

    const clock = this.incrementClock();
    const op: FormatApply = {
      type: 'format',
      start,
      end,
      attributes,
      clientId: this.clientId,
      clock,
    };

    this.applyFormatOp(op);
    this.invalidateCaches();
    this.notifyListeners();

    return op;
  }

  applyRemoteOp(op: EditorOp): void {
    if (this.isOpAlreadyApplied(op)) return;

    if (op.clientId in this.versionVector) {
      if (op.clock <= this.versionVector[op.clientId]) return;
    }

    switch (op.type) {
      case 'insert':
        this.applyInsertOp(op);
        break;
      case 'delete':
        this.applyDeleteOp(op);
        break;
      case 'format':
        this.applyFormatOp(op);
        break;
    }

    this.versionVector[op.clientId] = Math.max(
      this.versionVector[op.clientId] || 0,
      op.clock
    );

    this.invalidateCaches();
    this.notifyListeners();
  }

  applyOpsBatch(ops: EditorOp[]): void {
    for (const op of ops) {
      this.applyRemoteOp(op);
    }
  }

  getPendingOps(): EditorOp[] {
    return [...this.pendingOps];
  }

  flushPendingOps(): EditorOp[] {
    const ops = [...this.pendingOps];
    this.pendingOps = [];
    return ops;
  }

  private isOpAlreadyApplied(op: EditorOp): boolean {
    if (!(op.clientId in this.versionVector)) return false;
    return op.clock <= this.versionVector[op.clientId];
  }

  private applyInsertOp(op: CharInsert): void {
    const { clientId, clock, attributes } = op;
    const leftId = this.getCharIdAtVisualPosition(op.position - 1);
    const rightId = this.getCharIdAtVisualPosition(op.position);

    for (let i = 0; i < op.char.length; i++) {
      const charId = `${clientId}:${clock + i}`;
      if (this.chars.find(c => c.id === charId)) continue;

      const crdtChar: CRDTChar = {
        id: charId,
        char: op.char[i],
        originLeft: i === 0 ? leftId : `${clientId}:${clock + i - 1}`,
        originRight: i === op.char.length - 1 ? rightId : null,
        clientId,
        clock: clock + i,
        deleted: false,
        attributes: { ...attributes },
      };

      const insertIndex = this.findInsertIndex(crdtChar);
      this.chars.splice(insertIndex, 0, crdtChar);
    }
  }

  private applyDeleteOp(op: CharDelete): void {
    const visualChars = this.chars.filter(c => !c.deleted);
    let count = 0;

    for (const ch of visualChars) {
      if (count >= op.position && count < op.position + op.length) {
        ch.deleted = true;
      }
      count++;
    }
  }

  private applyFormatOp(op: FormatApply): void {
    const visualIndices: Array<{ index: number; crdtIndex: number }> = [];
    let vi = 0;

    for (let i = 0; i < this.chars.length; i++) {
      if (!this.chars[i].deleted) {
        visualIndices.push({ index: vi, crdtIndex: i });
        vi++;
      }
    }

    for (const { index, crdtIndex } of visualIndices) {
      if (index >= op.start && index < op.end) {
        const ch = this.chars[crdtIndex];
        ch.attributes = { ...ch.attributes, ...op.attributes };

        for (const [key, val] of Object.entries(op.attributes)) {
          if (val === null) {
            delete ch.attributes[key as keyof FormatAttrs];
          }
        }
      }
    }
  }

  private findInsertIndex(newChar: CRDTChar): number {
    let leftIndex = -1;
    let rightIndex = this.chars.length;

    if (newChar.originLeft) {
      leftIndex = this.chars.findIndex(c => c.id === newChar.originLeft);
    }

    if (newChar.originRight) {
      const idx = this.chars.findIndex(c => c.id === newChar.originRight);
      if (idx !== -1) rightIndex = idx;
    }

    if (leftIndex >= rightIndex) {
      return rightIndex;
    }

    for (let i = leftIndex + 1; i < rightIndex; i++) {
      const existing = this.chars[i];
      if (
        existing.originLeft === newChar.originLeft &&
        existing.originRight === newChar.originRight
      ) {
        if (newChar.clientId < existing.clientId) return i;
        if (
          newChar.clientId === existing.clientId &&
          newChar.clock < existing.clock
        )
          return i;
      }
    }

    return rightIndex;
  }

  private getCharIdAtVisualPosition(pos: number): string | null {
    let count = 0;
    for (const ch of this.chars) {
      if (!ch.deleted) {
        if (count === pos) return ch.id;
        count++;
      }
    }
    return null;
  }

  getUndoRedoOps(ops: EditorOp[]): EditorOp[] {
    const inverted: EditorOp[] = [];

    for (const op of [...ops].reverse()) {
      switch (op.type) {
        case 'insert':
          inverted.push({
            type: 'delete',
            position: op.position,
            length: op.char.length,
            clientId: this.clientId,
            clock: this.incrementClock(),
          });
          break;
        case 'delete':
          inverted.push({
            type: 'insert',
            position: op.position,
            char: this.getDeletedText(op.position, op.length),
            attributes: {},
            clientId: this.clientId,
            clock: this.incrementClock(),
          });
          break;
        case 'format':
          inverted.push({
            type: 'format',
            start: op.start,
            end: op.end,
            attributes: {}, // clear formatting
            clientId: this.clientId,
            clock: this.incrementClock(),
          });
          break;
      }
    }

    return inverted;
  }

  private getDeletedText(start: number, length: number): string {
    const visual = this.chars.filter(c => !c.deleted);
    return visual
      .slice(start, start + length)
      .map(c => c.char)
      .join('');
  }

  private invalidateCaches(): void {
    this.contentCache = null;
    this.formatRangesCache = null;
  }

  loadFromState(state: DocumentState): void {
    this.chars = [];
    this.versionVector = { ...state.versionVector };
    this.clock = state.versionVector[this.clientId] || 0;

    for (let i = 0; i < state.content.length; i++) {
      const charId = `init:${i}`;
      this.chars.push({
        id: charId,
        char: state.content[i],
        originLeft: i > 0 ? `init:${i - 1}` : null,
        originRight: i < state.content.length - 1 ? `init:${i + 1}` : null,
        clientId: 'init',
        clock: 0,
        deleted: false,
        attributes: {},
      });
    }

    this.invalidateCaches();
  }
}

import { openDB, type IDBPDatabase } from 'idb';

const DB_NAME = 'collab-editor-offline';
const DB_VERSION = 1;

export class IndexedDBManager {
  private db: IDBPDatabase | null = null;

  async open(): Promise<void> {
    this.db = await openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains('pending-ops')) {
          const store = db.createObjectStore('pending-ops', { keyPath: 'id' });
          store.createIndex('timestamp', 'timestamp');
        }
        if (!db.objectStoreNames.contains('snapshots')) {
          db.createObjectStore('snapshots', { keyPath: 'version' });
        }
        if (!db.objectStoreNames.contains('drafts')) {
          db.createObjectStore('drafts', { keyPath: 'key' });
        }
      },
    });
  }

  async close(): Promise<void> {
    this.db?.close();
    this.db = null;
  }

  async savePendingOp(op: { id: string; op: any; timestamp: number }): Promise<void> {
    if (!this.db) throw new Error('Database not open');
    await this.db.put('pending-ops', op);
  }

  async getPendingOps(): Promise<Array<{ id: string; op: any; timestamp: number }>> {
    if (!this.db) throw new Error('Database not open');
    return this.db.getAll('pending-ops');
  }

  async removePendingOp(id: string): Promise<void> {
    if (!this.db) throw new Error('Database not open');
    await this.db.delete('pending-ops', id);
  }

  async clearPendingOps(): Promise<void> {
    if (!this.db) throw new Error('Database not open');
    await this.db.clear('pending-ops');
  }

  async saveSnapshot(snapshot: { version: number; content: string; timestamp: number }): Promise<void> {
    if (!this.db) throw new Error('Database not open');
    await this.db.put('snapshots', snapshot);
  }

  async getLatestSnapshot(): Promise<{ version: number; content: string; timestamp: number } | undefined> {
    if (!this.db) throw new Error('Database not open');
    const all = await this.db.getAll('snapshots');
    all.sort((a, b) => b.version - a.version);
    return all[0];
  }

  async getAllSnapshots(): Promise<Array<{ version: number; content: string; timestamp: number }>> {
    if (!this.db) throw new Error('Database not open');
    return this.db.getAll('snapshots');
  }

  async saveDraft(key: string, data: any): Promise<void> {
    if (!this.db) throw new Error('Database not open');
    await this.db.put('drafts', { key, data });
  }

  async getDraft(key: string): Promise<any | undefined> {
    if (!this.db) throw new Error('Database not open');
    const record = await this.db.get('drafts', key);
    return record?.data;
  }
}

import { v4 as uuid } from 'uuid';
import type { EditorOp } from '../types/editor';
import type { PendingOp, WSMessage } from '../types/sync';

export class SyncEngine {
  private ws: WebSocket | null = null;
  private url: string;
  private reconnectDelay = 1000;
  private maxReconnectDelay = 30000;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private messageHandlers: Array<(msg: WSMessage) => void> = [];
  private statusHandlers: Array<(status: 'connected' | 'connecting' | 'disconnected') => void> = [];
  private isIntentionalClose = false;
  private pendingAcks: Set<string> = new Set();
  private ackHandlers: Array<(opIds: string[], serverVersion: number) => void> = [];
  private peerCount = 0;

  constructor(url: string) {
    this.url = url;
  }

  connect(): void {
    if (this.ws?.readyState === WebSocket.OPEN) return;
    this.isIntentionalClose = false;
    this.createConnection();
  }

  disconnect(): void {
    this.isIntentionalClose = true;
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    this.ws?.close();
    this.ws = null;
    this.statusHandlers.forEach(h => h('disconnected'));
  }

  private createConnection(): void {
    this.statusHandlers.forEach(h => h('connecting'));

    try {
      this.ws = new WebSocket(this.url);

      this.ws.onopen = () => {
        this.reconnectDelay = 1000;
        this.statusHandlers.forEach(h => h('connected'));
      };

      this.ws.onmessage = (event) => {
        try {
          const msg: WSMessage = JSON.parse(event.data);
          this.messageHandlers.forEach(h => h(msg));
        } catch {
          // ignore malformed messages
        }
      };

      this.ws.onclose = () => {
        if (!this.isIntentionalClose) {
          this.statusHandlers.forEach(h => h('disconnected'));
          this.scheduleReconnect();
        }
      };

      this.ws.onerror = () => {
        if (!this.isIntentionalClose) {
          this.statusHandlers.forEach(h => h('disconnected'));
        }
      };
    } catch {
      if (!this.isIntentionalClose) {
        this.scheduleReconnect();
      }
    }
  }

  private scheduleReconnect(): void {
    if (this.reconnectTimer) clearTimeout(this.reconnectTimer);
    this.reconnectTimer = setTimeout(() => {
      this.reconnectDelay = Math.min(
        this.reconnectDelay * 1.5,
        this.maxReconnectDelay
      );
      this.createConnection();
    }, this.reconnectDelay);
  }

  sendOp(op: EditorOp): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
    const msg: WSMessage = {
      type: 'op_batch',
      ops: [op],
      serverVersion: 0,
    };
    this.ws.send(JSON.stringify(msg));
  }

  sendOpsBatch(ops: EditorOp[]): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN || ops.length === 0) return;
    const msg: WSMessage = {
      type: 'op_batch',
      ops,
      serverVersion: 0,
    };
    this.ws.send(JSON.stringify(msg));
  }

  sendCursor(
    clientId: string,
    position: number,
    selection: { anchor: number; head: number } | undefined,
    user: { id: string; name: string; color: string }
  ): void {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) return;
    const msg: WSMessage = {
      type: 'cursor',
      clientId,
      position,
      selection,
      user,
    };
    this.ws.send(JSON.stringify(msg));
  }

  getPeerCount(): number {
    return this.peerCount;
  }

  onMessage(handler: (msg: WSMessage) => void): () => void {
    this.messageHandlers.push(handler);
    return () => {
      this.messageHandlers = this.messageHandlers.filter(h => h !== handler);
    };
  }

  onStatusChange(handler: (status: 'connected' | 'connecting' | 'disconnected') => void): () => void {
    this.statusHandlers.push(handler);
    return () => {
      this.statusHandlers = this.statusHandlers.filter(h => h !== handler);
    };
  }

  onAck(handler: (opIds: string[], serverVersion: number) => void): () => void {
    this.ackHandlers.push(handler);
    return () => {
      this.ackHandlers = this.ackHandlers.filter(h => h !== handler);
    };
  }

  isConnected(): boolean {
    return this.ws?.readyState === WebSocket.OPEN;
  }
}

import type { EditorOp, CharInsert, CharDelete, FormatApply, DocumentState, FormatAttrs, FormatRange } from '@/types/editor';
import { v4 as uuid } from 'uuid';

interface CRDTChar {
  id: string;
  char: string;
  position: number;
  attributes: FormatAttrs;
  clientId: string;
  clock: number;
  isDeleted: boolean;
  lamport: number;
}

export class CRDTManager {
  private chars: CRDTChar[] = [];
  private clientId: string;
  private clock: number = 0;
  private versionVector: Record<string, number> = {};
  private lamportClock: number = 0;

  constructor(clientId?: string) {
    this.clientId = clientId ?? uuid();
  }

  getClientId(): string {
    return this.clientId;
  }

  getClock(): number {
    return this.clock;
  }

  getVersionVector(): Record<string, number> {
    return { ...this.versionVector };
  }

  tick(): number {
    this.clock += 1;
    return this.clock;
  }

  advanceLamport(): number {
    this.lamportClock += 1;
    return this.lamportClock;
  }

  getLamport(): number {
    return this.lamportClock;
  }

  updateLamport(remote: number): void {
    this.lamportClock = Math.max(this.lamportClock, remote) + 1;
  }

  localInsert(position: number, text: string, attributes: FormatAttrs = {}): CharInsert[] {
    const ops: CharInsert[] = [];
    for (let i = 0; i < text.length; i++) {
      const clock = this.tick();
      const char: CRDTChar = {
        id: `${this.clientId}:${clock}`,
        char: text[i],
        position,
        attributes: { ...attributes },
        clientId: this.clientId,
        clock,
        isDeleted: false,
        lamport: this.advanceLamport(),
      };
      this.chars.push(char);
      ops.push({
        type: 'insert',
        position,
        char: text[i],
        attributes: { ...attributes },
        clientId: this.clientId,
        clock,
      });
      position++;
    }
    this.versionVector[this.clientId] = Math.max(this.versionVector[this.clientId] || 0, this.clock);
    return ops;
  }

  localDelete(position: number, length: number): CharDelete[] {
    const ops: CharDelete[] = [];
    if (length > 0) {
      const clock = this.tick();
      ops.push({
        type: 'delete',
        position,
        length,
        clientId: this.clientId,
        clock,
      });
    }
    this.versionVector[this.clientId] = Math.max(this.versionVector[this.clientId] || 0, this.clock);
    return ops;
  }

  localFormat(start: number, end: number, attributes: FormatAttrs): FormatApply[] {
    const ops: FormatApply[] = [];
    const clock = this.tick();
    ops.push({
      type: 'format',
      start,
      end,
      attributes,
      clientId: this.clientId,
      clock,
    });
    this.versionVector[this.clientId] = Math.max(this.versionVector[this.clientId] || 0, this.clock);
    return ops;
  }

  applyRemoteInsert(op: CharInsert): boolean {
    if (op.clientId === this.clientId) return false;

    const existing = this.chars.find(c => c.id === `${op.clientId}:${op.clock}`);
    if (existing) return false;

    const char: CRDTChar = {
      id: `${op.clientId}:${op.clock}`,
      char: op.char,
      position: op.position,
      attributes: { ...op.attributes },
      clientId: op.clientId,
      clock: op.clock,
      isDeleted: false,
      lamport: this.advanceLamport(),
    };
    this.chars.push(char);
    this.versionVector[op.clientId] = Math.max(this.versionVector[op.clientId] || 0, op.clock);
    return true;
  }

  applyRemoteDelete(op: CharDelete): boolean {
    if (op.clientId === this.clientId) return false;
    this.versionVector[op.clientId] = Math.max(this.versionVector[op.clientId] || 0, op.clock);
    return true;
  }

  applyRemoteFormat(op: FormatApply): boolean {
    if (op.clientId === this.clientId) return false;
    this.versionVector[op.clientId] = Math.max(this.versionVector[op.clientId] || 0, op.clock);
    return true;
  }

  getContent(): string {
    const sorted = this.chars
      .filter(c => !c.isDeleted)
      .sort((a, b) => {
        if (a.position !== b.position) return a.position - b.position;
        return a.lamport - b.lamport;
      });

    return sorted.map(c => c.char).join('');
  }

  getFormats(): FormatRange[] {
    const ranges: FormatRange[] = [];
    let current: FormatRange | null = null;

    const sorted = this.chars
      .filter(c => !c.isDeleted)
      .sort((a, b) => a.position - b.position);

    for (let i = 0; i < sorted.length; i++) {
      const attrs = sorted[i].attributes;
      const pos = i;

      if (!current) {
        current = { start: pos, end: pos + 1, attributes: { ...attrs } };
        continue;
      }

      if (areAttrsEqual(current.attributes, attrs)) {
        current.end = pos + 1;
      } else {
        ranges.push(current);
        current = { start: pos, end: pos + 1, attributes: { ...attrs } };
      }
    }

    if (current) {
      ranges.push(current);
    }

    return ranges;
  }

  getState(): DocumentState {
    return {
      content: this.getContent(),
      formats: this.getFormats(),
      version: Object.values(this.versionVector).reduce((a, b) => a + b, 0),
      versionVector: { ...this.versionVector },
    };
  }

  snapshot(): DocumentState {
    return this.getState();
  }

  applyFullState(state: DocumentState): void {
    this.chars = [];
    for (let i = 0; i < state.content.length; i++) {
      this.chars.push({
        id: `restore:${i}`,
        char: state.content[i],
        position: i,
        attributes: this.findFormatAt(i, state.formats),
        clientId: 'system',
        clock: 0,
        isDeleted: false,
        lamport: i,
      });
    }
    this.versionVector = { ...state.versionVector };
  }

  private findFormatAt(pos: number, formats: FormatRange[]): FormatAttrs {
    const attrs: FormatAttrs = {};
    for (const f of formats) {
      if (pos >= f.start && pos < f.end) {
        Object.assign(attrs, f.attributes);
      }
    }
    return attrs;
  }
}

function areAttrsEqual(a: FormatAttrs, b: FormatAttrs): boolean {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  for (const k of keys) {
    if ((a as any)[k] !== (b as any)[k]) return false;
  }
  return true;
}

import type { EditorOp, DocumentState } from '@/types/editor';
import type { WSMessage, OpBatchMessage, CursorMessage, ConnectionState } from '@/types/sync';
import { CRDTManager } from './CRDTManager';
import { OfflineQueue } from './OfflineQueue';
import { IndexedDBManager } from './IndexedDBManager';

type SyncCallback = (txn: SyncTransaction) => void;

export interface SyncTransaction {
  ops: EditorOp[];
  documentVersion: number;
  cursors: CursorMessage[];
  source: 'local' | 'remote';
}

export class SyncEngine {
  private crdt: CRDTManager;
  private offlineQueue: OfflineQueue;
  private idbManager: IndexedDBManager;
  private ws: WebSocket | null = null;
  private connectionState: ConnectionState = 'disconnected';
  private listeners: Set<SyncCallback> = new Set();
  private peers: number = 0;
  private url: string;
  private pendingAcks: Set<string> = new Set();
  private lastSyncVersion: number = 0;
  private currentUser: { id: string; name: string; color: string };
  private cursorPosition: number = 0;

  constructor(crdt: CRDTManager, url: string, user: { id: string; name: string; color: string }) {
    this.crdt = crdt;
    this.url = url;
    this.currentUser = user;
    this.offlineQueue = new OfflineQueue();
    this.idbManager = new IndexedDBManager('collab-editor');
  }

  async initialize(): Promise<void> {
    await this.idbManager.init();
    const stored = await this.idbManager.loadDocument();
    if (stored) {
      this.crdt.applyFullState(stored);
      this.lastSyncVersion = stored.version;
    }
    await this.flushOfflineQueue();
  }

  connect(): void {
    this.setConnectionState('connecting');
    try {
      this.ws = new WebSocket(this.url);
      this.ws.onopen = () => this.handleOpen();
      this.ws.onmessage = (evt) => this.handleMessage(evt.data);
      this.ws.onclose = () => this.handleClose();
      this.ws.onerror = () => this.handleError();
    } catch {
      this.setConnectionState('disconnected');
    }
  }

  disconnect(): void {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.setConnectionState('disconnected');
  }

  onSync(cb: SyncCallback): () => void {
    this.listeners.add(cb);
    return () => this.listeners.delete(cb);
  }

  getConnectionState(): ConnectionState {
    return this.connectionState;
  }

  getPeers(): number {
    return this.peers;
  }

  getPendingCount(): number {
    return this.offlineQueue.size();
  }

  setCursorPosition(position: number, selection?: { anchor: number; head: number }): void {
    this.cursorPosition = position;
    this.sendCursor(position, selection);
  }

  private handleOpen(): void {
    this.setConnectionState('connected');
    this.syncState();
    this.flushOfflineQueue();
  }

  private handleMessage(data: string): void {
    try {
      const msg: WSMessage = JSON.parse(data);
      switch (msg.type) {
        case 'state_sync':
          this.handleStateSync(msg);
          break;
        case 'op_batch':
          this.handleOpBatch(msg);
          break;
        case 'cursor':
          this.handleCursor(msg);
          break;
        case 'ack':
          this.handleAck(msg);
          break;
      }
    } catch {
      // ignore malformed messages
    }
  }

  private handleClose(): void {
    this.setConnectionState('disconnected');
    this.scheduleReconnect();
  }

  private handleError(): void {
    this.setConnectionState('disconnected');
  }

  private scheduleReconnect(): void {
    setTimeout(() => {
      if (this.connectionState === 'disconnected') {
        this.setConnectionState('reconnecting');
        this.connect();
      }
    }, 2000 + Math.random() * 3000);
  }

  private handleStateSync(msg: any): void {
    const state: DocumentState = {
      content: msg.content,
      formats: [],
      version: msg.documentVersion,
      versionVector: msg.versionVector,
    };
    if (msg.documentVersion > this.lastSyncVersion) {
      this.crdt.applyFullState(state);
      this.lastSyncVersion = msg.documentVersion;
      this.notifyListeners({ ops: [], documentVersion: msg.documentVersion, cursors: [], source: 'remote' });
    }
  }

  private handleOpBatch(msg: OpBatchMessage): void {
    const remoteOps: EditorOp[] = [];
    for (const op of msg.ops) {
      switch (op.type) {
        case 'insert':
          if (this.crdt.applyRemoteInsert(op)) {
            remoteOps.push(op);
          }
          break;
        case 'delete':
          this.crdt.applyRemoteDelete(op);
          remoteOps.push(op);
          break;
        case 'format':
          this.crdt.applyRemoteFormat(op);
          remoteOps.push(op);
          break;
      }
    }
    this.lastSyncVersion = msg.serverVersion;
    if (remoteOps.length > 0) {
      this.notifyListeners({
        ops: remoteOps,
        documentVersion: msg.serverVersion,
        cursors: [],
        source: 'remote',
      });
    }
  }

  private handleCursor(msg: CursorMessage): void {
    if (msg.clientId !== this.currentUser.id) {
      this.notifyListeners({
        ops: [],
        documentVersion: this.lastSyncVersion,
        cursors: [msg],
        source: 'remote',
      });
    }
  }

  private handleAck(msg: { type: 'ack'; opIds: string[]; serverVersion: number }): void {
    for (const id of msg.opIds) {
      this.pendingAcks.delete(id);
      this.offlineQueue.remove(id);
    }
    this.lastSyncVersion = msg.serverVersion;
  }

  sendOps(ops: EditorOp[]): void {
    const batched: string[] = [];
    for (const op of ops) {
      const id = `${op.clientId}:${op.clock}`;
      batched.push(id);
      this.pendingAcks.add(id);
      this.offlineQueue.enqueue(id, op);
    }

    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: 'op_batch',
        ops,
        clientId: this.crdt.getClientId(),
      }));
    } else {
      this.offlineQueue.persist();
    }
  }

  private sendCursor(position: number, selection?: { anchor: number; head: number }): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: 'cursor',
        clientId: this.currentUser.id,
        position,
        selection,
        user: this.currentUser,
      }));
    }
  }

  private syncState(): void {
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: 'request_sync',
        lastVersion: this.lastSyncVersion,
      }));
    }
  }

  private async flushOfflineQueue(): Promise<void> {
    const pending = this.offlineQueue.getAll();
    if (pending.length > 0 && this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        type: 'op_batch',
        ops: pending.map(p => p.op),
        clientId: this.crdt.getClientId(),
      }));
      this.offlineQueue.clear();
    }
  }

  private setConnectionState(state: ConnectionState): void {
    this.connectionState = state;
  }

  private notifyListeners(txn: SyncTransaction): void {
    for (const listener of this.listeners) {
      try {
        listener(txn);
      } catch {
        // isolate listener failures
      }
    }
  }

  async persistDocument(): Promise<void> {
    const state = this.crdt.getState();
    await this.idbManager.saveDocument(state);
  }

  disconnect(): void {
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.setConnectionState('disconnected');
  }
}

import type { EditorOp } from '@/types/editor';

interface QueueEntry {
  id: string;
  op: EditorOp;
  timestamp: number;
  retries: number;
}

const STORAGE_KEY = 'offline_queue_v1';

export class OfflineQueue {
  private queue: QueueEntry[] = [];

  enqueue(id: string, op: EditorOp): void {
    this.queue.push({ id, op, timestamp: Date.now(), retries: 0 });
  }

  remove(id: string): void {
    this.queue = this.queue.filter(e => e.id !== id);
  }

  getAll(): QueueEntry[] {
    return [...this.queue];
  }

  size(): number {
    return this.queue.length;
  }

  clear(): void {
    this.queue = [];
    this.save();
  }

  persist(): void {
    this.save();
  }

  async load(): Promise<void> {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      if (data) {
        const entries: QueueEntry[] = JSON.parse(data);
        this.queue = entries;
      }
    } catch {
      this.queue = [];
    }
  }

  private save(): void {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.queue));
    } catch {
      // storage full or unavailable
    }
  }
}

import { openDB, type IDBPDatabase } from 'idb';
import type { DocumentState } from '@/types/editor';

const DB_VERSION = 1;
const DOC_STORE = 'documents';
const VERSION_STORE = 'versions';

interface StoredDocument {
  id: string;
  state: DocumentState;
  updatedAt: number;
}

interface StoredVersion {
  id: string;
  version: number;
  snapshot: string;
  timestamp: number;
  author: string;
  message: string;
}

export class IndexedDBManager {
  private db: IDBPDatabase | null = null;
  private dbName: string;

  constructor(dbName: string) {
    this.dbName = dbName;
  }

  async init(): Promise<void> {
    this.db = await openDB(this.dbName, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains(DOC_STORE)) {
          db.createObjectStore(DOC_STORE, { keyPath: 'id' });
        }
        if (!db.objectStoreNames.contains(VERSION_STORE)) {
          const store = db.createObjectStore(VERSION_STORE, { keyPath: 'id' });
          store.createIndex('version', 'version', { unique: false });
        }
      },
    });
  }

  async saveDocument(state: DocumentState): Promise<void> {
    if (!this.db) return;
    const doc: StoredDocument = {
      id: 'current',
      state,
      updatedAt: Date.now(),
    };
    await this.db.put(DOC_STORE, doc);
  }

  async loadDocument(): Promise<DocumentState | null> {
    if (!this.db) return null;
    const doc = await this.db.get(DOC_STORE, 'current') as StoredDocument | undefined;
    return doc?.state ?? null;
  }

  async saveVersion(version: StoredVersion): Promise<void> {
    if (!this.db) return;
    await this.db.put(VERSION_STORE, version);
  }

  async getVersions(): Promise<StoredVersion[]> {
    if (!this.db) return [];
    return this.db.getAllFromIndex(VERSION_STORE, 'version');
  }

  async getVersion(versionId: string): Promise<StoredVersion | null> {
    if (!this.db) return null;
    return (await this.db.get(VERSION_STORE, versionId)) as StoredVersion | undefined ?? null;
  }
}

import type { CursorPosition, UserInfo } from '@/types/presence';

const CURSOR_TIMEOUT_MS = 30_000;

export class CursorManager {
  private cursors: Map<string, CursorPosition> = new Map();
  private cleanupInterval: ReturnType<typeof setInterval> | null = null;

  start(): void {
    this.cleanupInterval = setInterval(() => this.cleanupStale(), 5000);
  }

  stop(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
  }

  updateCursor(cursor: CursorPosition): void {
    cursor.lastUpdated = Date.now();
    this.cursors.set(cursor.clientId, cursor);
  }

  removeCursor(clientId: string): void {
    this.cursors.delete(clientId);
  }

  getAllCursors(): CursorPosition[] {
    return Array.from(this.cursors.values())
      .filter(c => Date.now() - c.lastUpdated < CURSOR_TIMEOUT_MS);
  }

  getCursorPosition(clientId: string): CursorPosition | undefined {
    return this.cursors.get(clientId);
  }

  private cleanupStale(): void {
    const now = Date.now();
    for (const [clientId, cursor] of this.cursors) {
      if (now - cursor.lastUpdated > CURSOR_TIMEOUT_MS) {
        this.cursors.delete(clientId);
      }
    }
  }
}

import type { Comment, CommentReply, UserRef, CommentOp } from '@/types/comments';
import { v4 as uuid } from 'uuid';

export class CommentManager {
  private comments: Comment[] = [];

  addComment(position: number, text: string, author: UserRef): Comment {
    const comment: Comment = {
      id: uuid(),
      documentVersion: 0,
      position,
      text,
      author,
      replies: [],
      resolved: false,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };
    this.comments.push(comment);
    return comment;
  }

  addReply(commentId: string, text: string, author: UserRef): CommentReply | null {
    const comment = this.comments.find(c => c.id === commentId);
    if (!comment) return null;

    const reply: CommentReply = {
      id: uuid(),
      text,
      author,
      createdAt: Date.now(),
    };
    comment.replies.push(reply);
    comment.updatedAt = Date.now();
    return reply;
  }

  resolveComment(commentId: string): boolean {
    const comment = this.comments.find(c => c.id === commentId);
    if (!comment) return false;
    comment.resolved = true;
    comment.updatedAt = Date.now();
    return true;
  }

  reopenComment(commentId: string): boolean {
    const comment = this.comments.find(c => c.id === commentId);
    if (!comment) return false;
    comment.resolved = false;
    comment.updatedAt = Date.now();
    return true;
  }

  deleteComment(commentId: string): boolean {
    const idx = this.comments.findIndex(c => c.id === commentId);
    if (idx === -1) return false;
    this.comments.splice(idx, 1);
    return true;
  }

  getAll(): Comment[] {
    return [...this.comments];
  }

  getForPosition(position: number): Comment[] {
    return this.comments.filter(c => c.position === position);
  }

  getUnresolved(): Comment[] {
    return this.comments.filter(c => !c.resolved);
  }

  applyRemoteOp(op: CommentOp): void {
    switch (op.type) {
      case 'add_comment':
        this.comments.push({
          id: op.payload.id || uuid(),
          documentVersion: op.payload.documentVersion || 0,
          position: op.payload.position || 0,
          text: op.payload.text || '',
          author: op.payload.author || { id: '', name: '' },
          replies: [],
          resolved: false,
          createdAt: Date.now(),
          updatedAt: Date.now(),
        });
        break;
      case 'reply':
        if (op.commentId && op.payload.id) {
          const c = this.comments.find(x => x.id === op.commentId);
          if (c) {
            c.replies.push({
              id: op.payload.id,
              text: op.payload.text || '',
              author: op.payload.author || { id: '', name: '' },
              createdAt: Date.now(),
            });
            c.updatedAt = Date.now();
          }
        }
        break;
      case 'resolve':
        if (op.commentId) this.resolveComment(op.commentId);
        break;
      case 'delete':
        if (op.commentId) this.deleteComment(op.commentId);
        break;
    }
  }
}

import type { VersionEntry, VersionDiff } from '@/types/version';
import type { DocumentSnapshot } from '@/types/editor';
import { v4 as uuid } from 'uuid';
import { IndexedDBManager } from './IndexedDBManager';

export class VersionManager {
  private versions: VersionEntry[] = [];
  private idb: IndexedDBManager;

  constructor() {
    this.idb = new IndexedDBManager('collab-editor');
  }

  async init(): Promise<void> {
    await this.idb.init();
    const stored = await this.idb.getVersions();
    if (stored.length > 0) {
      this.versions = stored.map(s => ({
        id: s.id,
        version: s.version,
        timestamp: s.timestamp,
        author: s.author,
        message: s.message,
        snapshot: JSON.parse(s.snapshot) as DocumentSnapshot,
        isAutoSave: s.message === 'Auto-save',
      }));
    }
  }

  saveVersion(snapshot: DocumentSnapshot, author: string, message?: string): VersionEntry {
    const entry: VersionEntry = {
      id: uuid(),
      version: this.versions.length + 1,
      timestamp: Date.now(),
      author,
      message: message || 'Manual save',
      snapshot,
      isAutoSave: !message,
    };
    this.versions.push(entry);
    this.idb.saveVersion({
      id: entry.id,
      version: entry.version,
      snapshot: JSON.stringify(entry.snapshot),
      timestamp: entry.timestamp,
      author: entry.author,
      message: entry.message,
    });
    return entry;
  }

  getAll(): VersionEntry[] {
    return [...this.versions].sort((a, b) => b.version - a.version);
  }

  getByVersion(version: number): VersionEntry | undefined {
    return this.versions.find(v => v.version === version);
  }

  diff(fromVersion: number, toVersion: number): VersionDiff {
    const from = this.getByVersion(fromVersion);
    const to = this.getByVersion(toVersion);
    if (!from || !to) {
      return { fromVersion, toVersion, changes: [] };
    }
    return computeDiff(from.snapshot, to.snapshot, fromVersion, toVersion);
  }

  revertTo(version: number): DocumentSnapshot | null {
    const entry = this.getByVersion(version);
    return entry?.snapshot ?? null;
  }
}

function computeDiff(from: DocumentSnapshot, to: DocumentSnapshot, fromV: number, toV: number): VersionDiff {
  const changes: VersionDiff['changes'] = [];
  const fromContent = from.content;
  const toContent = to.content;

  let i = 0;
  let j = 0;

  while (i < fromContent.length && j < toContent.length) {
    if (fromContent[i] === toContent[j]) {
      i++;
      j++;
    } else {
      let deletionLen = 0;
      const deletionStart = i;
      while (i < fromContent.length && (i >= toContent.length || fromContent[i] !== toContent[j])) {
        i++;
        deletionLen++;
      }
      let insertionLen = 0;
      const insertionStart = j;
      while (j < toContent.length && (j >= fromContent.length || toContent[j] !== fromContent[i])) {
        j++;
        insertionLen++;
      }
      if (deletionLen > 0) {
        changes.push({ type: 'deletion', position: deletionStart, text: fromContent.slice(deletionStart, i) });
      }
      if (insertionLen > 0) {
        changes.push({ type: 'insertion', position: insertionStart, text: toContent.slice(insertionStart, j) });
      }
    }
  }

  if (i < fromContent.length) {
    changes.push({ type: 'deletion', position: i, text: fromContent.slice(i) });
  }
  if (j < toContent.length) {
    changes.push({ type: 'insertion', position: j, text: toContent.slice(j) });
  }

  return { fromVersion: fromV, toVersion: toV, changes };
}

