import { create } from 'zustand';
import type { DocumentState, FormatAttrs, EditorOp } from '@/types/editor';
import { CRDTManager } from '@/services/CRDTManager';
import { SyncEngine } from '@/services/SyncEngine';
import { CursorManager } from '@/services/CursorManager';

interface EditorStore {
  crdt: CRDTManager;
  syncEngine: SyncEngine | null;
  cursorManager: CursorManager;
  documentState: DocumentState;
  user: { id: string; name: string; color: string };
  localCursorPosition: number;
  isConnected: boolean;
  peerCount: number;
  pendingOps: number;

  initialize: (userId: string, userName: string, userColor: string, wsUrl: string) => Promise<void>;
  setSyncEngine: (engine: SyncEngine) => void;
  insertText: (position: number, text: string, attrs?: FormatAttrs) => void;
  deleteText: (start: number, length: number) => void;
  applyFormat: (start: number, end: number, attrs: FormatAttrs) => void;
  setCursorPosition: (pos: number, selection?: { anchor: number; head: number }) => void;
  updateDocumentState: (state: DocumentState) => void;
  setConnected: (connected: boolean) => void;
  setPeerCount: (count: number) => void;
  setPendingOps: (count: number) => void;
  disconnect: () => void;
}

export const useEditorStore = create<EditorStore>((set, get) => ({
  crdt: new CRDTManager(),
  syncEngine: null,
  cursorManager: new CursorManager(),
  documentState: { content: '', formats: [], version: 0, versionVector: {} },
  user: { id: '', name: '', color: '' },
  localCursorPosition: 0,
  isConnected: false,
  peerCount: 0,
  pendingOps: 0,

  initialize: async (userId, userName, userColor, wsUrl) => {
    const crdt = new CRDTManager(userId);
    get().cursorManager.start();
    const engine = new SyncEngine(crdt, wsUrl, { id: userId, name: userName, color: userColor });
    await engine.initialize();
    engine.connect();
    set({
      crdt,
      syncEngine: engine,
      user: { id: userId, name: userName, color: userColor },
      documentState: crdt.getState(),
    });
  },

  setSyncEngine: (engine) => set({ syncEngine: engine }),

  insertText: (position, text, attrs = {}) => {
    const { crdt, syncEngine } = get();
    const ops = crdt.localInsert(position, text, attrs);
    if (ops.length > 0 && syncEngine) {
      syncEngine.sendOps(ops);
    }
    set({ documentState: crdt.getState() });
  },

  deleteText: (start, length) => {
    const { crdt, syncEngine } = get();
    const ops = crdt.localDelete(start, length);
    if (ops.length > 0 && syncEngine) {
      syncEngine.sendOps(ops);
    }
    set({ documentState: crdt.getState() });
  },

  applyFormat: (start, end, attrs) => {
    const { crdt, syncEngine } = get();
    const ops = crdt.localFormat(start, end, attrs);
    if (ops.length > 0 && syncEngine) {
      syncEngine.sendOps(ops);
    }
    set({ documentState: crdt.getState() });
  },

  setCursorPosition: (pos, selection) => {
    const { syncEngine } = get();
    if (syncEngine) {
      syncEngine.setCursorPosition(pos, selection);
    }
    set({ localCursorPosition: pos });
  },

  updateDocumentState: (state) => set({ documentState: state }),

  setConnected: (connected) => set({ isConnected: connected }),
  setPeerCount: (count) => set({ peerCount: count }),
  setPendingOps: (count) => set({ pendingOps: count }),

  disconnect: () => {
    const { syncEngine, cursorManager } = get();
    cursorManager.stop();
    syncEngine?.disconnect();
    set({ syncEngine: null, isConnected: false });
  },
}));

import { create } from 'zustand';
import type { CursorPosition } from '@/types/presence';

interface PresenceStore {
  remoteCursors: CursorPosition[];
  setCursors: (cursors: CursorPosition[]) => void;
  addCursor: (cursor: CursorPosition) => void;
  removeCursor: (clientId: string) => void;
}

export const usePresenceStore = create<PresenceStore>((set) => ({
  remoteCursors: [],
  setCursors: (cursors) => set({ remoteCursors: cursors }),
  addCursor: (cursor) =>
    set((state) => ({
      remoteCursors: [
        ...state.remoteCursors.filter((c) => c.clientId !== cursor.clientId),
        cursor,
      ],
    })),
  removeCursor: (clientId) =>
    set((state) => ({
      remoteCursors: state.remoteCursors.filter((c) => c.clientId !== clientId),
    })),
}));

import { create } from 'zustand';
import type { Comment } from '@/types/comments';
import type { UserRef } from '@/types/comments';
import { CommentManager } from '@/services/CommentManager';

interface CommentStore {
  commentManager: CommentManager;
  comments: Comment[];
  showResolved: boolean;

  addComment: (position: number, text: string, author: UserRef) => Comment;
  addReply: (commentId: string, text: string, author: UserRef) => void;
  resolveComment: (commentId: string) => void;
  reopenComment: (commentId: string) => void;
  deleteComment: (commentId: string) => void;
  toggleShowResolved: () => void;
  getCommentsAtPosition: (position: number) => Comment[];
  refresh: () => void;
}

export const useCommentStore = create<CommentStore>((set, get) => ({
  commentManager: new CommentManager(),
  comments: [],
  showResolved: false,

  addComment: (position, text, author) => {
    const comment = get().commentManager.addComment(position, text, author);
    set({ comments: get().commentManager.getAll() });
    return comment;
  },
  addReply: (commentId, text, author) => {
    get().commentManager.addReply(commentId, text, author);
    set({ comments: get().commentManager.getAll() });
  },
  resolveComment: (commentId) => {
    get().commentManager.resolveComment(commentId);
    set({ comments: get().commentManager.getAll() });
  },
  reopenComment: (commentId) => {
    get().commentManager.reopenComment(commentId);
    set({ comments: get().commentManager.getAll() });
  },
  deleteComment: (commentId) => {
    get().commentManager.deleteComment(commentId);
    set({ comments: get().commentManager.getAll() });
  },
  toggleShowResolved: () => set((s) => ({ showResolved: !s.showResolved })),
  getCommentsAtPosition: (position) => get().commentManager.getForPosition(position),
  refresh: () => set({ comments: get().commentManager.getAll() }),
}));

import { create } from 'zustand';
import type { VersionEntry, VersionDiff } from '@/types/version';
import type { DocumentSnapshot } from '@/types/editor';
import { VersionManager } from '@/services/VersionManager';

interface VersionStore {
  versionManager: VersionManager;
  versions: VersionEntry[];
  selectedVersion: VersionEntry | null;
  diffResult: VersionDiff | null;
  initialized: boolean;

  init: () => Promise<void>;
  saveVersion: (snapshot: DocumentSnapshot, author: string, message?: string) => void;
  selectVersion: (version: VersionEntry | null) => void;
  diff: (fromVersion: number, toVersion: number) => void;
  revertTo: (version: number) => DocumentSnapshot | null;
  refresh: () => void;
}

export const useVersionStore = create<VersionStore>((set, get) => ({
  versionManager: new VersionManager(),
  versions: [],
  selectedVersion: null,
  diffResult: null,
  initialized: false,

  init: async () => {
    const vm = get().versionManager;
    await vm.init();
    set({ versions: vm.getAll(), initialized: true });
  },

  saveVersion: (snapshot, author, message) => {
    const vm = get().versionManager;
    vm.saveVersion(snapshot, author, message);
    set({ versions: vm.getAll() });
  },

  selectVersion: (version) => set({ selectedVersion: version, diffResult: null }),

  diff: (fromVersion, toVersion) => {
    const vm = get().versionManager;
    const result = vm.diff(fromVersion, toVersion);
    set({ diffResult: result });
  },

  revertTo: (version) => {
    return get().versionManager.revertTo(version);
  },

  refresh: () => {
    set({ versions: get().versionManager.getAll() });
  },
}));

import { create } from 'zustand';
import type { ConnectionState } from '@/types/sync';

interface SyncStore {
  connectionState: ConnectionState;
  peers: number;
  pendingOps: number;
  lastSyncAt: number | null;
  error: string | null;

  setConnectionState: (state: ConnectionState) => void;
  setPeers: (count: number) => void;
  setPendingOps: (count: number) => void;
  setLastSyncAt: (timestamp: number) => void;
  setError: (error: string | null) => void;
}

export const useSyncStore = create<SyncStore>((set) => ({
  connectionState: 'disconnected',
  peers: 0,
  pendingOps: 0,
  lastSyncAt: null,
  error: null,

  setConnectionState: (state) => set({ connectionState: state }),
  setPeers: (count) => set({ peers: count }),
  setPendingOps: (count) => set({ pendingOps: count }),
  setLastSyncAt: (timestamp) => set({ lastSyncAt: timestamp }),
  setError: (error) => set({ error }),
}));
